mapper.select:


    deleted = 0
     and name like concat('%', #{name}, '%')
     and gender = #{gender}
     and phone like concat('%', #{phone}, '%')
     and role = #{role}
     and title like concat('%', #{title}, '%')
     and education like concat('%', #{education}, '%')
     and id_card like concat('%', #{idCard}, '%')
     and emergency_contact like concat('%', #{emergencyContact}, '%')
     and emergency_phone like concat('%', #{emergencyPhone}, '%')
     and entry_date = #{entryDate}
     and status = #{status}

order by id desc
